sys_script.script:
(function executeRule(current, previous) {
    var status = (current.application_status + "").toLowerCase();
    if (status !== "approved") return;
    var disGr = new GlideRecord("x_2200409_schola_1_scholarship_disbursement");
    disGr.addQuery("application", current.getUniqueValue());
    disGr.query();
    if (!disGr.hasNext()) {
        var prog = current.scholarship_program.getRefRecord();
        var approvedAmount = 0;
        if (prog.isValidRecord()) {
            approvedAmount = parseFloat(prog.scholarship_amount) || 0;
        }
        var dis = new GlideRecord("x_2200409_schola_1_scholarship_disbursement");
        dis.initialize();
        dis.application = current.getUniqueValue();
        dis.student = current.student;
        dis.scholarship_program = current.scholarship_program;
        dis.approved_amount = approvedAmount;
        dis.payment_status = "pending";
        dis.disbursement_date = new GlideDateTime();
        dis.insert();
    }
})(current, previous);
